"""Paired budget/Pareto summary of completed context-sigma reconstruction, no new render."""
from datetime import datetime, timezone
import json
from pathlib import Path
import numpy as np
from study_noise_neighbourhoods import ROOT, git, sha256


def compare(a, b):
    keys = ('mse', 'signal_distortion', 'residual_noise', 'cross')
    delta = {k: float(np.mean(b['full'][k])-np.mean(a['full'][k])) for k in keys}
    if not np.isclose(delta['mse'], delta['signal_distortion']+delta['residual_noise']+delta['cross'], atol=1e-10, rtol=1e-10):
        raise ValueError('Difference budget fails')
    signal = delta['signal_distortion']; noise = delta['residual_noise']; tolerance = 1e-12
    if signal <= tolerance and noise <= tolerance and min(signal, noise) < -tolerance:
        dominance = 'b_improves_both'
    elif signal >= -tolerance and noise >= -tolerance and max(signal, noise) > tolerance:
        dominance = 'a_improves_both'
    elif abs(signal) <= tolerance and abs(noise) <= tolerance:
        dominance = 'equal'
    else:
        dominance = 'tradeoff'
    return dict(delta_b_minus_a=delta, signal_noise_dominance=dominance,
        peak_delta_b_minus_a=b['peak_directional_signal_ratio']-a['peak_directional_signal_ratio']
            if 'peak_directional_signal_ratio' in a and 'peak_directional_signal_ratio' in b else None)


def run():
    parent = ROOT/'docs/validation/raw/reconstruction-sigma-contextes-axes-bruit-v001-20261026T223259Z.json'
    digest = sha256(parent); data = json.loads(parent.read_text(encoding='utf-8'))
    records = []
    comparisons = (('frame_a_context_mad', 'frame_a_context_variance'),
                   ('frame_a_global_mad', 'frame_a_context_mad'),
                   ('common', 'frame_a_context_variance'))
    for row in data['records']:
        for a, b in comparisons:
            records.append(dict(fold=row['fold'], iso=data['folds'][row['fold']]['iso'], shape=row['shape'],
                amplitude=row['amplitude'], width=row['width'], direction=row['direction'], a=a, b=b,
                **compare(row['metrics'][a], row['metrics'][b])))
    summaries = []
    for a, b in comparisons:
        for iso in (100, 1600, 6400, 51200):
            for shape in ('flat', 'gaussian', 'step'):
                selected = [r for r in records if r['a'] == a and r['b'] == b and r['iso'] == iso and r['shape'] == shape]
                summaries.append(dict(a=a, b=b, iso=iso, shape=shape, count=len(selected),
                    mean_delta={key: float(np.mean([r['delta_b_minus_a'][key] for r in selected]))
                                for key in ('mse', 'signal_distortion', 'residual_noise', 'cross')},
                    dominance_counts={name: sum(r['signal_noise_dominance'] == name for r in selected)
                        for name in ('b_improves_both', 'a_improves_both', 'equal', 'tradeoff')},
                    mean_peak_delta=float(np.mean([r['peak_delta_b_minus_a'] for r in selected])) if shape == 'gaussian' else None))
    if sha256(parent) != digest:
        raise ValueError('Parent changed')
    now = datetime.now(timezone.utc)
    output = ROOT/'docs/validation/raw'/f"bilan-compromis-sigma-contextes-axes-bruit-v001-{now.strftime('%Y%m%dT%H%M%SZ')}.json"
    result = dict(schema_version=1, data_version=1, completed_at_utc=now.isoformat(), commit=git('rev-parse', 'HEAD'),
        runner_sha256=sha256(Path(__file__)), runner_source=Path(__file__).read_text(encoding='utf-8'),
        parent=dict(path=str(parent), sha256=digest), records=records, summaries=summaries,
        rules='Readexisting196relatedstatesONLY,3pairedcomparisons;588rowsNOTnewtests. DecomposeDeltaMSE=DeltaSignalDistortion+DeltaNoise+DeltaCross. ParetoonSignal/NoiseONLY,crosskeptseparate,notMSEequivalence. No statisticalindependence,pvalue,thresholdoptimization,strengthfit orrender.',
        limitations='Fourrealnoisefields,fixedforms,andconditionaltransportbudget. Bettervarianceestimate neednotoptimizeMSEwithbiasedpilot. Paretoison3planeaverage,notperpixel/hue/perceptualguarantee. No new validationorproduction.')
    with output.open('x', encoding='utf-8') as handle:
        json.dump(result, handle, ensure_ascii=False, indent=1, allow_nan=False)
    print(output, flush=True)
    for row in summaries:
        if row['a'] == 'frame_a_context_mad':
            print(row, flush=True)


if __name__ == '__main__':
    run()
